package com.termux.app.workspace;
import android.app.*;import android.view.*;import android.widget.*;import com.termux.app.TermuxActivity;import com.termux.R;import com.termux.terminal.TerminalSession;import java.lang.reflect.*;
import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.Config;import static org.junit.Assert.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=28,application=Application.class)
public class SessionHeaderPanelTest {
 private TermuxActivity a;private WorkspaceController controller;
 @Before public void setup()throws Exception{a=Robolectric.buildActivity(TermuxActivity.class).get();a.setTheme(R.style.Theme_Termux_Black);a.setContentView(R.layout.activity_termux);Field tv=TermuxActivity.class.getDeclaredField("mTerminalView");tv.setAccessible(true);tv.set(a,a.findViewById(R.id.terminal_view));WorkspaceLanguage.select(a,"ru");WorkspaceText.resources=WorkspaceLanguage.wrap(a).getResources();controller=new WorkspaceController(a);}
 @After public void close(){controller.close();}
 private Object field(String key)throws Exception{Field f=WorkspaceController.class.getDeclaredField(key);f.setAccessible(true);return f.get(controller);}
 private void call(String method)throws Exception{Method m=WorkspaceController.class.getDeclaredMethod(method);m.setAccessible(true);m.invoke(controller);}
 private View text(View v,String label){if(v instanceof TextView&&label.contentEquals(((TextView)v).getText()))return v;if(v instanceof ViewGroup)for(int i=0;i<((ViewGroup)v).getChildCount();i++){View found=text(((ViewGroup)v).getChildAt(i),label);if(found!=null)return found;}return null;}
 @Test public void emptyHeaderOpensSidebarWithoutCreatingOrStartingSessions()throws Exception{
  WorkspaceStore store=(WorkspaceStore)field("store");int count=store.sessions.size();a.findViewById(R.id.workspace_header).findViewWithTag("workspace-menu").performClick();WorkspaceSidebar menu=(WorkspaceSidebar)field("sidebar");assertTrue(menu.dialog.isShowing());assertNotNull(text(menu.body,"Создать сессию"));assertNotNull(text(menu.body,"Создать чат"));assertEquals(count,store.sessions.size());assertNull(a.getCurrentSession());assertEquals(View.GONE,a.findViewById(R.id.workspace_tab_scroll).getVisibility());menu.dialog.dismiss();
 }
 @Test public void startupCancellationIsStillReachableForTheSelectedMenuOwner()throws Exception{
  WorkspaceLanguage.select(a,"ru");WorkspaceStore store=(WorkspaceStore)field("store");store.sessions.clear();WorkspaceStore.Session p=new WorkspaceStore.Session();p.name="Ubuntu";p.environment="ubuntu";p.directory="/tmp";p.saved=true;p.startup="echo synthetic-first\necho synthetic-second";store.sessions.add(p);call("showSidebar");WorkspaceSidebar menu=(WorkspaceSidebar)field("sidebar");ViewGroup frame=menu.body.findViewWithTag("sidebar-session-"+p.id);((ViewGroup)frame.getChildAt(0)).getChildAt(0).performClick();ViewGroup actions=(ViewGroup)frame.getChildAt(1);for(String label:new String[]{"Настройки сессии","Пакеты окружения","Файлы окружения","Отменить команды запуска"})assertNotNull(text(actions,label));
  text(actions,"Отменить команды запуска").performClick();org.robolectric.Shadows.shadowOf(android.os.Looper.getMainLooper()).idle();AlertDialog confirmation=org.robolectric.shadows.ShadowAlertDialog.getLatestAlertDialog();assertTrue(confirmation.isShowing());assertNotNull(text(confirmation.getWindow().getDecorView(),"Отменить следующие шаги запуска? Ниже все настроенные команды. Уже выполняемая команда продолжит работу."));java.io.File marker=new java.io.File(SessionShell.directory(a.getFilesDir(),p.id),"cancel-startup");assertFalse(marker.exists());confirmation.getButton(-2).performClick();org.robolectric.Shadows.shadowOf(android.os.Looper.getMainLooper()).idle();assertFalse(marker.exists());assertNull(a.getCurrentSession());assertEquals("echo synthetic-first\necho synthetic-second",p.startup);
 }
}
